INSERT INTO `message` (`id`,`language`,`translation`) SELECT s.id,'am','ԱՋԱԿՑՈՒԹՅՈՒՆ' FROM `source_message` s WHERE s.category='app' AND s.message='SUPPORT' ON DUPLICATE KEY UPDATE `translation`=VALUES(`translation`);
INSERT INTO `source_message` (`category`,`message`) SELECT 'app', 'Read More' WHERE NOT EXISTS (SELECT 1 FROM `source_message` WHERE `category`='app' AND `message`='Read More');
INSERT INTO `message` (`id`,`language`,`translation`) SELECT s.id,'am','Կարդալ ավելին' FROM `source_message` s WHERE s.category='app' AND s.message='Read More' ON DUPLICATE KEY UPDATE `translation`=VALUES(`translation`);
